document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("insulation-form"),n=document.getElementById("insulation-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const t=parseFloat(document.getElementById("insulation-length").value),a=parseFloat(document.getElementById("insulation-width").value),i=document.getElementById("insulation-application").value,[s,o,r]=document.getElementById("insulation-climate").value.split(","),p=parseFloat(document.getElementById("insulation-existing").value),[l,d]=document.getElementById("insulation-type").value.split(",").map(Number),c=parseFloat(document.getElementById("insulation-depth").value);if(t<=0||a<=0)return n.textContent="Please enter valid dimensions.",void 0;const u=t*a;let v;switch(i){case"attic":v=parseInt(s.substring(1));break;case"wall":default:v=parseInt(o.substring(1));break;case"floor":case"ceiling":case"basement":v=parseInt(r.substring(1))}const m=Math.max(0,v-p),g=m/l,h=g<=c,f=c*l;let $=u*d,b=u;"wall"!==i&&"ceiling"!==i||(b=.93*u);const y=p/v,x=(p+m)/v,E=(x-y)/(1-y);let F;switch(i){case"attic":F=500;break;case"wall":default:F=300;break;case"floor":case"basement":F=200;break;case"ceiling":F=250}const R=F*E*(u/1e3),I=$/Math.max(R,1);let k="";if(l<=3.6){k=`<p>Bags needed: ${Math.ceil(u*g/30)} (blown-in coverage)</p>`}else{k=`<p>Packages needed: ${Math.ceil(b/40)} (batt/board packages)</p>`}n.innerHTML=`\n        <div class="result-section">\n          <h4>Project Specifications:</h4>\n          <p>Area: ${t}' × ${a}' = ${u} sq ft</p>\n          <p>Application: ${i.charAt(0).toUpperCase()+i.slice(1)}</p>\n          <p>Target R-value: R-${v}</p>\n          <p>Existing R-value: R-${p}</p>\n          <p><strong>Additional R-value needed: R-${m}</strong></p>\n        </div>\n        \n        <div class="result-thickness">\n          <h4>Insulation Thickness:</h4>\n          <p><strong>Thickness needed: ${g.toFixed(1)}"</strong></p>\n          <p>Available cavity depth: ${c}"</p>\n          <p>Cavity utilization: ${h?"✅ Fits perfectly":"⚠️ Exceeds cavity depth"}</p>\n          ${h?"":`\n          <p><strong>Maximum R-value in cavity: R-${f.toFixed(0)}</strong></p>\n          <p><em>Consider continuous insulation or thicker framing</em></p>\n          `}\n        </div>\n        \n        <div class="result-materials">\n          <h4>Material Requirements:</h4>\n          <p>Coverage area: ${b.toFixed(0)} sq ft</p>\n          ${k}\n          <p><strong>Material cost: $${$.toFixed(0)}</strong></p>\n          <p>Cost per sq ft: $${d.toFixed(2)}</p>\n        </div>\n        \n        <div class="result-performance">\n          <h4>Energy Performance:</h4>\n          <p>Current insulation level: ${(100*y).toFixed(0)}% of target</p>\n          <p>After upgrade: ${(100*x).toFixed(0)}% of target</p>\n          <p>Performance improvement: ${(100*E).toFixed(0)}%</p>\n          <p>R-value per inch: R-${l}</p>\n        </div>\n        \n        <div class="result-savings">\n          <h4>Estimated Energy Savings:</h4>\n          <p><strong>Annual savings: $${R.toFixed(0)}</strong></p>\n          <p>Payback period: ${I.toFixed(1)} years</p>\n          <p>10-year savings: $${(10*R).toFixed(0)}</p>\n          <p><em>Savings vary by energy costs and usage patterns</em></p>\n        </div>\n        \n        <div class="result-installation">\n          <h4>Installation Considerations:</h4>\n          ${"wall"===i?"\n          <p>🔧 Retrofit: blown-in through small holes</p>\n          <p>🏗️ New construction: batts between studs</p>\n          ":""}\n          ${"attic"===i?"\n          <p>🏠 Access: through attic hatch or eave vents</p>\n          <p>🌡️ Air sealing: seal gaps before insulating</p>\n          ":""}\n          <p>🧤 Safety: wear protective equipment</p>\n          <p>📏 Measure twice: verify cavity dimensions</p>\n          <p>💨 Ventilation: maintain proper airflow</p>\n        </div>\n        \n        <div class="result-alternatives">\n          <h4>Alternative Solutions:</h4>\n          ${h?"":"\n          <p>🔧 Continuous insulation over sheathing</p>\n          <p>🏗️ Furring strips for additional depth</p>\n          <p>🌡️ Higher R-value per inch materials</p>\n          "}\n          <p>💰 Rebates: check utility rebate programs</p>\n          <p>📋 Tax credits: federal/state incentives available</p>\n        </div>\n        \n        <div class="result-tips">\n          <h4>Professional Recommendations:</h4>\n          <p>🔍 Energy audit before major upgrades</p>\n          <p>💨 Air seal before adding insulation</p>\n          <p>🌡️ Maintain proper vapor barriers</p>\n          <p>📞 Consider professional installation for spray foam</p>\n          <p>📋 Check building code requirements</p>\n        </div>\n        \n        <div class="result-comfort">\n          <h4>Additional Benefits:</h4>\n          <p>🌡️ Improved temperature control</p>\n          <p>🔇 Reduced noise transmission</p>\n          <p>💧 Better moisture control</p>\n          <p>🏠 Increased home value</p>\n          <p>🌱 Reduced carbon footprint</p>\n        </div>\n      `})});